79	With a single attention head, averaging inhibits this.\n4To illustrate why the dot products get large, assume that the components of q and k are independent random\nvariables with mean 0 and variance 1. Then their dot product, q · k = Pdk\ni=1 qiki, has mean 0 and variance dk.\n4	{"type": "text", "page": 4, "source": "attention.pdf", "_node_content": "{\\"id_\\": \\"36943a66-d21e-482c-a192-1c9ba0027660\\", \\"embedding\\": null, \\"metadata\\": {\\"type\\": \\"text\\", \\"page\\": 4, \\"source\\": \\"attention.pdf\\"}, \\"excluded_embed_metadata_keys\\": [], \\"excluded_llm_metadata_keys\\": [], \\"relationships\\": {\\"1\\": {\\"node_id\\": \\"7c46c85f-3fc4-4f09-a074-16b4c08d4469\\", \\"node_type\\": \\"4\\", \\"metadata\\": {\\"type\\": \\"text\\", \\"page\\": 4, \\"source\\": \\"attention.pdf\\"}, \\"hash\\": \\"4b78a1f2cfcc4dffd47567d88073d7b400eaeaa119a824bea0f8a3e5aa8eacfe\\", \\"class_name\\": \\"RelatedNodeInfo\\"}, \\"2\\": {\\"node_id\\": \\"ba36e7f4-0679-47d8-acfd-77136217314a\\", \\"node_type\\": \\"1\\", \\"metadata\\": {\\"type\\": \\"text\\", \\"page\\": 4, \\"source\\": \\"attention.pdf\\"}, \\"hash\\": \\"d3638f90728269c0aee4ee2f8c5ca0e94af03f8c794c15801864d9a4abf6ec3f\\", \\"class_name\\": \\"RelatedNodeInfo\\"}}, \\"metadata_template\\": \\"{key}: {value}\\", \\"metadata_separator\\": \\"\\\\n\\", \\"text\\": \\"\\", \\"mimetype\\": \\"text/plain\\", \\"start_char_idx\\": 2172, \\"end_char_idx\\": 2448, \\"text_template\\": \\"{metadata_str}\\\\n\\\\n{content}\\", \\"class_name\\": \\"TextNode\\"}", "_node_type": "TextNode", "document_id": "7c46c85f-3fc4-4f09-a074-16b4c08d4469", "doc_id": "7c46c85f-3fc4-4f09-a074-16b4c08d4469", "ref_doc_id": "7c46c85f-3fc4-4f09-a074-16b4c08d4469"}	36943a66-d21e-482c-a192-1c9ba0027660	[0.005267495,-0.029964259,0.045956407,0.015818788,0.013596824,-0.028226798,0.03951795,0.06517351,0.091704294,0.058812905,0.029943109,0.07298002,0.07109001,-0.03849551,-0.06235603,0.04261997,-0.012371595,-0.0412823,-0.07391485,0.009